import java.util.ArrayList;
import java.util.List;

public class ParallelSumDemo {
    private static final Object LOCK = new Object();
    private static int lockedCounter = 0;

    public static void main(String[] args) throws InterruptedException {
        final int n = 1000, workers = 4, chunk = n / workers;
        long[] partial = new long[workers]; // one slot per thread: nothing shared, no lock needed
        List<Thread> threads = new ArrayList<>();

        for (int w = 0; w < workers; w++) {
            final int id = w, from = w * chunk + 1, to = (w + 1) * chunk;
            Thread t = new Thread(() -> {
                long sum = 0;
                for (int i = from; i <= to; i++) sum += i;
                partial[id] = sum;
                for (int i = 0; i < 1000; i++) {
                    synchronized (LOCK) { lockedCounter++; } // shared field: guard every access
                }
            });
            threads.add(t);
            t.start(); // run() now executes on a new thread
        }
        for (Thread t : threads) t.join(); // wait for all; join also makes their writes visible here

        long total = 0;
        for (int w = 0; w < workers; w++) {
            System.out.println("worker " + w + " summed " + (w * chunk + 1) + ".." + (w + 1) * chunk + " = " + partial[w]);
            total += partial[w];
        }
        System.out.println("total = " + total + " (formula n(n+1)/2 = " + (long) n * (n + 1) / 2 + ")");
        System.out.println("locked counter = " + lockedCounter + " (expected " + workers * 1000 + ")");
    }
}

