    std::vector<long long> partial(workers, 0); // one slot per thread: nothing shared, no lock needed
    int lockedCounter = 0;
    std::mutex lock;
    std::vector<std::thread> threads;

    for (int w = 0; w < workers; ++w) {
        int from = w * chunk + 1, to = (w + 1) * chunk;
        threads.emplace_back([&, w, from, to] { // the thread starts running as soon as it is constructed
            long long sum = 0;
            for (int i = from; i <= to; ++i) sum += i;
            partial[w] = sum;
            for (int i = 0; i < 1000; ++i) {
                std::lock_guard<std::mutex> guard(lock); // shared variable: guard every access
                ++lockedCounter;
            }
        });
    }
    for (auto& t : threads) t.join(); // wait for all before reading their results

