import java.util.List;

public class FactorialThreadDemo {
    // The subclass IS a thread: it carries its own work in run()
    static class FactorialThread extends Thread {
        private final int n;
        private final Thread creator = Thread.currentThread();
        long result;
        boolean ranOnOtherThread;

        FactorialThread(int n) {
            super("factorial-" + n); // thread name, handy in debuggers and stack traces
            this.n = n;
        }

        @Override
        public void run() {
            long product = 1;
            for (int i = 2; i <= n; i++) product *= i;
            result = product;
            ranOnOtherThread = Thread.currentThread() != creator;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        List<FactorialThread> threads = List.of(new FactorialThread(5), new FactorialThread(10), new FactorialThread(15));
        System.out.println("created " + threads.size() + " thread objects; running before start(): " + threads.get(0).isAlive());

        for (FactorialThread t : threads) t.start();
        System.out.println("started all " + threads.size() + "; main thread now waits in join()");
        for (FactorialThread t : threads) t.join(); // results are safe to read only after join()

        for (FactorialThread t : threads) {
            System.out.println(t.n + "! = " + t.result + " (ran on a separate thread: " + t.ranOnOtherThread + ")");
        }
        boolean anyAlive = threads.stream().anyMatch(Thread::isAlive);
        System.out.println("any running after join(): " + anyAlive);
        // threads.get(0).start() here would throw IllegalThreadStateException: a thread starts only once

        FactorialThread direct = new FactorialThread(6);
        direct.run(); // plain method call: no new thread is created
        System.out.println("run() called directly: 6! = " + direct.result + " (ran on a separate thread: " + direct.ranOnOtherThread + ")");
    }
}

