// std::thread is not meant to be subclassed, so this class owns one, mirroring java.lang.Thread
class FactorialThread {
public:
    explicit FactorialThread(int n) : n(n), creator_(std::this_thread::get_id()) {}

    void run() {
        long long product = 1;
        for (int i = 2; i <= n; ++i) product *= i;
        result = product;
        ranOnOtherThread = std::this_thread::get_id() != creator_;
    }

    void start() { thread_ = std::thread(&FactorialThread::run, this); } // the OS thread begins here
    void join() { thread_.join(); }
    bool isAlive() const { return thread_.joinable(); } // true from start() until join()

    const int n;
    long long result = 0;
    bool ranOnOtherThread = false;

private:
    std::thread::id creator_;
    std::thread thread_;
};

int main() {
    std::cout << std::boolalpha;
    std::vector<FactorialThread> threads;
    for (int n : {5, 10, 15}) threads.emplace_back(n); // build all before starting: no moves after start()
    std::cout << "created " << threads.size() << " thread objects; running before start(): " << threads[0].isAlive() << "\n";

    for (auto& t : threads) t.start();
    std::cout << "started all " << threads.size() << "; main thread now waits in join()\n";
    for (auto& t : threads) t.join(); // results are safe to read only after join()

    bool anyAlive = false;
    for (const auto& t : threads) {
        std::cout << t.n << "! = " << t.result << " (ran on a separate thread: " << t.ranOnOtherThread << ")\n";
        anyAlive = anyAlive || t.isAlive();
    }
    std::cout << "any running after join(): " << anyAlive << "\n";

    FactorialThread direct(6);
    direct.run(); // plain function call: no new thread is created
    std::cout << "run() called directly: 6! = " << direct.result << " (ran on a separate thread: " << direct.ranOnOtherThread << ")\n";
}

