const { Worker, isMainThread, parentPort, workerData } = require('node:worker_threads');

// Node has no Thread class to extend, so this class wraps a Worker the way java.lang.Thread wraps an OS thread
class FactorialThread {
  constructor(n) {
    this.n = n;
    this.result = 0;
    this.ranOnOtherThread = false;
    this.alive = false;
  }

  run() {
    let product = 1;
    for (let i = 2; i <= this.n; i++) product *= i;
    this.result = product;
    this.ranOnOtherThread = !isMainThread;
  }

  start() {
    this.alive = true;
    const worker = new Worker(__filename, { workerData: this.n }); // re-runs this file on a new thread
    worker.on('message', (fields) => Object.assign(this, fields));
    this.finished = new Promise((resolve) => worker.on('exit', () => { this.alive = false; resolve(); }));
  }

  join() {
    return this.finished;
  }
}

async function main() {
  const threads = [5, 10, 15].map((n) => new FactorialThread(n));
  console.log(`created ${threads.length} thread objects; running before start(): ${threads[0].alive}`);

  threads.forEach((t) => t.start());
  console.log(`started all ${threads.length}; main thread now waits in join()`);
  for (const t of threads) await t.join(); // results are safe to read only after join()

  for (const t of threads) {
    console.log(`${t.n}! = ${t.result} (ran on a separate thread: ${t.ranOnOtherThread})`);
  }
  console.log(`any running after join(): ${threads.some((t) => t.alive)}`);

  const direct = new FactorialThread(6);
  direct.run(); // plain method call: no new thread is created
  console.log(`run() called directly: 6! = ${direct.result} (ran on a separate thread: ${direct.ranOnOtherThread})`);
}

if (isMainThread) {
  main();
} else {
  const t = new FactorialThread(workerData);
  t.run();
  parentPort.postMessage({ result: t.result, ranOnOtherThread: t.ranOnOtherThread });
}

