import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class RunnableTasksDemo {
    // A task, not a thread: it is free to extend another class if it needs to
    static class WordCountTask implements Runnable {
        final String name;
        final String text;
        int count;

        WordCountTask(String name, String text) {
            this.name = name;
            this.text = text;
        }

        @Override
        public void run() {
            count = text.split(" ").length;
        }
    }

    static final String[][] DOCS = {
        {"doc-A", "threads share one heap"},
        {"doc-B", "a runnable is just a task to run"},
        {"doc-C", "join waits patiently"},
    };

    public static void main(String[] args) throws Exception {
        // Part 1: each Runnable handed to its own new Thread
        List<WordCountTask> tasks = new ArrayList<>();
        List<Thread> threads = new ArrayList<>();
        for (String[] doc : DOCS) {
            WordCountTask task = new WordCountTask(doc[0], doc[1]);
            Thread thread = new Thread(task);
            tasks.add(task);
            threads.add(thread);
            thread.start();
        }
        for (Thread thread : threads) thread.join();
        for (WordCountTask task : tasks) {
            System.out.println("thread counted " + task.name + ": " + task.count + " words");
        }

        // Part 2: the same work as Callable lambdas on a pool of 2 reusable threads
        ExecutorService pool = Executors.newFixedThreadPool(2);
        List<Future<Integer>> futures = new ArrayList<>();
        for (String[] doc : DOCS) futures.add(pool.submit(() -> doc[1].split(" ").length));
        List<Integer> counts = new ArrayList<>();
        for (Future<Integer> future : futures) counts.add(future.get()); // blocks until that task is done
        pool.shutdown(); // accept no new tasks; threads exit after the queue drains

        System.out.println("futures in submit order: " + counts);
        System.out.println("total words: " + counts.stream().mapToInt(Integer::intValue).sum());
    }
}

