#include <functional>
#include <future>
#include <iostream>
#include <sstream>
#include <string>
#include <thread>
#include <vector>

int countWords(const std::string& text) {
    std::istringstream in(text);
    std::string word;
    int count = 0;
    while (in >> word) ++count;
    return count;
}

// A task, not a thread: any callable object can be handed to std::thread
struct WordCountTask {
    std::string name;
    std::string text;
    int count = 0;
    void operator()() { count = countWords(text); } // like Runnable.run(): no args, no return value
};

int main() {
    std::vector<WordCountTask> tasks = {
        {"doc-A", "threads share one heap"},
        {"doc-B", "a runnable is just a task to run"},
        {"doc-C", "join waits patiently"},
    };

    // Part 1: each task handed to its own std::thread
    std::vector<std::thread> threads;
    for (auto& task : tasks) threads.emplace_back(std::ref(task)); // std::ref: run this object, not a copy
    for (auto& t : threads) t.join();
    for (const auto& task : tasks) {
        std::cout << "thread counted " << task.name << ": " << task.count << " words\n";
    }

    // Part 2: the same work through std::async; each std::future delivers one result
    std::vector<std::future<int>> futures;
    for (const auto& task : tasks) futures.push_back(std::async(std::launch::async, countWords, task.text));
    int total = 0;
    std::cout << "futures in submit order: [";
    for (std::size_t i = 0; i < futures.size(); ++i) {
        int count = futures[i].get(); // blocks until that task is done
        total += count;
        std::cout << (i ? ", " : "") << count;
    }
    std::cout << "]\n";
    std::cout << "total words: " << total << "\n";
}

