const { Worker, isMainThread, parentPort, workerData } = require('node:worker_threads');

const DOCS = [
  ['doc-A', 'threads share one heap'],
  ['doc-B', 'a runnable is just a task to run'],
  ['doc-C', 'join waits patiently'],
];

const countWords = (text) => text.split(' ').length;

// Workers receive data, not closures: the task is "run countWords on this text"
function startTask(text) {
  const worker = new Worker(__filename, { workerData: text });
  return new Promise((resolve, reject) => {
    worker.once('message', resolve); // the Promise plays the role of a Future
    worker.once('error', reject);
  });
}

async function main() {
  // Part 1: one worker per task, then wait for all of them
  const results = await Promise.all(DOCS.map(([, text]) => startTask(text)));
  DOCS.forEach(([name], i) => console.log(`thread counted ${name}: ${results[i]} words`));

  // Part 2: keep the futures in submit order and await each one
  const futures = DOCS.map(([, text]) => startTask(text));
  const counts = [];
  for (const future of futures) counts.push(await future); // waits until that task is done
  console.log(`futures in submit order: [${counts.join(', ')}]`);
  console.log(`total words: ${counts.reduce((a, b) => a + b, 0)}`);
}

if (isMainThread) {
  main();
} else {
  parentPort.postMessage(countWords(workerData));
}

