import java.util.ArrayList;
import java.util.List;

public class SynchronizedCounterDemo {
    // Replays count++ step by step, strictly alternating T1 and T2 (the worst case for a race)
    static int simulate(boolean synced) {
        String[] program = synced ? new String[]{"lock", "read", "write", "unlock"} : new String[]{"read", "write"};
        int count = 0;
        String owner = null;
        int[] pc = new int[2], register = new int[2];
        for (int turn = 0; pc[0] < program.length || pc[1] < program.length; turn = 1 - turn) {
            int t = turn;
            String name = "T" + (t + 1);
            if (pc[t] == program.length) continue;
            switch (program[pc[t]]) {
                case "lock" -> {
                    if (owner != null) {
                        System.out.println(name + " blocks: lock held by " + owner);
                        continue; // loses its turn without advancing
                    }
                    owner = name;
                    System.out.println(name + " acquires the lock");
                }
                case "read" -> {
                    register[t] = count;
                    System.out.println(name + " reads count = " + count);
                }
                case "write" -> {
                    count = register[t] + 1;
                    System.out.println(name + " writes " + register[t] + " + 1 = " + count);
                }
                default -> {
                    owner = null;
                    System.out.println(name + " releases the lock");
                }
            }
            pc[t]++;
        }
        return count;
    }

    static class SyncCounter {
        private int count = 0;
        synchronized void increment() { count++; } // one thread at a time per SyncCounter object
        synchronized int get() { return count; }
    }

    public static void main(String[] args) throws InterruptedException {
        System.out.println("-- count++ without a lock --");
        System.out.println("result: " + simulate(false) + " (expected 2)");
        System.out.println("-- count++ inside synchronized --");
        System.out.println("result: " + simulate(true) + " (expected 2)");

        SyncCounter counter = new SyncCounter();
        List<Thread> threads = new ArrayList<>();
        for (int i = 0; i < 4; i++) {
            Thread t = new Thread(() -> { for (int k = 0; k < 25_000; k++) counter.increment(); });
            threads.add(t);
            t.start();
        }
        for (Thread t : threads) t.join();
        System.out.println("-- 4 real threads x 25000 synchronized increments --");
        System.out.println("count = " + counter.get() + " (expected 100000)");
    }
}

