import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.ReentrantLock;

public class LockOrderingDemo {
    static final class Account {
        final int id;
        int balance; // guarded by lock
        final ReentrantLock lock = new ReentrantLock();

        Account(int id, int balance) {
            this.id = id;
            this.balance = balance;
        }
    }

    static final AtomicInteger transfers = new AtomicInteger(); // thread-safe without a lock

    // One global rule: lower id first. Opposite transfers then cannot wait on each other in a cycle.
    static Account[] lockOrder(Account from, Account to) {
        return from.id < to.id ? new Account[]{from, to} : new Account[]{to, from};
    }

    static void transfer(Account from, Account to, int amount) {
        Account[] order = lockOrder(from, to);
        order[0].lock.lock();
        try {
            order[1].lock.lock();
            try {
                from.balance -= amount; // debit and credit happen together or not at all
                to.balance += amount;
                transfers.incrementAndGet();
            } finally {
                order[1].lock.unlock();
            }
        } finally {
            order[0].lock.unlock();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Account a = new Account(1, 1000), b = new Account(2, 1000);
        System.out.println("naive order: T1 holds 1 wants 2, T2 holds 2 wants 1 -> deadlock possible");
        System.out.println("transfer 1->2 locks: " + lockOrder(a, b)[0].id + ", " + lockOrder(a, b)[1].id);
        System.out.println("transfer 2->1 locks: " + lockOrder(b, a)[0].id + ", " + lockOrder(b, a)[1].id);

        Thread t1 = new Thread(() -> { for (int i = 0; i < 500; i++) transfer(a, b, 1); });
        Thread t2 = new Thread(() -> { for (int i = 0; i < 500; i++) transfer(b, a, 2); });
        t1.start();
        t2.start();
        t1.join();
        t2.join();

