// One global rule: lower id first. Opposite transfers then cannot wait on each other in a cycle.
std::pair<Account*, Account*> lockOrder(Account& from, Account& to) {
    return from.id < to.id ? std::make_pair(&from, &to) : std::make_pair(&to, &from);
}

void transfer(Account& from, Account& to, int amount) {
