// Shared memory layout: [lock of account 1, lock of account 2, balance 1, balance 2, transfers]
const LOCK = { 1: 0, 2: 1 };
const BALANCE = { 1: 2, 2: 3 };
const TRANSFERS = 4;

function lock(cells, i) {
  while (Atomics.compareExchange(cells, i, 0, 1) !== 0) Atomics.wait(cells, i, 1);
}

function unlock(cells, i) {
  Atomics.store(cells, i, 0);
  Atomics.notify(cells, i, 1);
}

// One global rule: lower id first. Opposite transfers then cannot wait on each other in a cycle.
const lockOrder = (from, to) => (from < to ? [from, to] : [to, from]);

function transfer(cells, from, to, amount) {
  const [first, second] = lockOrder(from, to);
  lock(cells, LOCK[first]);
  lock(cells, LOCK[second]);
  cells[BALANCE[from]] -= amount; // debit and credit happen together or not at all
  cells[BALANCE[to]] += amount;
  unlock(cells, LOCK[second]);
  unlock(cells, LOCK[first]);
  Atomics.add(cells, TRANSFERS, 1); // atomic counter, no lock needed
}

